def investigate(context, acquire):
    hist = acquire("history")
    # Family: put mode in {ignore, replace, upsert}, trigger in {none, after_insert},
    # channel in {changes, total_changes, total_changes_sum}.
    # We simulate each candidate and keep those consistent with all receipts.

    def simulate(actions, mode, trig, chan):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value for committed; pending per connection
        committed = {}
        # per-connection transaction state: None or dict of pending ops
        # We model main and other separately.
        # For simplicity track pending dict per connection and open flag.
        pending = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() per connection
        last_changes = {"main": 0, "other": 0}
        # log rows count (trigger)
        log_count = 0

        def apply_op(conn, op, key, value):
            nonlocal log_count
            # returns number of direct row changes for this statement
            # operate on the effective view: committed + pending[conn]
            base = committed
            pend = pending[conn]
            if pend is None:
                view = base
            else:
                view = dict(base)
                view.update(pend)
            changes = 0
            if op == "put":
                if key in view:
                    if mode == "ignore":
                        changes = 0
                    elif mode == "replace":
                        changes = 1
                        if pend is None:
                            committed[key] = value
                        else:
                            pend[key] = value
                    else:  # upsert
                        changes = 1
                        if pend is None:
                            committed[key] = value
                        else:
                            pend[key] = value
                else:
                    changes = 1
                    if pend is None:
                        committed[key] = value
                    else:
                        pend[key] = value
            elif op == "update":
                if key in view:
                    changes = 1
                    if pend is None:
                        committed[key] = value
                    else:
                        pend[key] = value
                else:
                    changes = 0
            elif op == "delete":
                if key in view:
                    changes = 1
                    if pend is None:
                        committed.pop(key, None)
                    else:
                        pend.pop(key, None)
                else:
                    changes = 0
            if changes > 0 and trig:
                log_count += 1
            return changes

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = {}
            elif op == "commit":
                if pending[conn] is not None:
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                c = apply_op(conn, op, key, value)
                last_changes[conn] = c
                tc[conn] += c

        if chan == "changes":
            ch = last_changes["main"]
        elif chan == "total_changes":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_sum"]

    candidates = []
    for m in modes:
        for t in trigs:
            for c in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(acts, m, t, c)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((m, t, c))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for (m, t, c) in candidates:
        ch, cc, cs = simulate(actions, m, t, c)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

