def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, trig, chan, actions):
        committed = {}
        tx = {"main": None, "other": None}
        tc = {"main": 0, "other": 0}
        last_changes = 0

        def view_of(conn):
            if tx[conn] is not None:
                v = dict(committed)
                for k, val in tx[conn].items():
                    if val is None:
                        v.pop(k, None)
                    else:
                        v[k] = val
                return v
            return committed

        def do_write(conn, key, value, is_put):
            nonlocal last_changes
            view = view_of(conn)
            existed = key in view
            old = view.get(key)
            changed = False
            if is_put:
                if put_mode == "ignore":
                    if not existed:
                        changed = True
                elif put_mode == "replace":
                    changed = True
                else:
                    if not existed:
                        changed = True
                    elif old != value:
                        changed = True
            else:
                if existed and old != value:
                    changed = True
            if not changed:
                last_changes = 0
                return
            if tx[conn] is not None:
                tx[conn][key] = value
            else:
                committed[key] = value
            last_changes = 1
            tc[conn] += 1

        def do_delete(conn, key):
            nonlocal last_changes
            view = view_of(conn)
            if key in view:
                if tx[conn] is not None:
                    tx[conn][key] = None
                else:
                    del committed[key]
                last_changes = 1
                tc[conn] += 1
            else:
                last_changes = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_write(conn, act["key"], act["value"], True)
            elif op == "update":
                do_write(conn, act["key"], act["value"], False)
            elif op == "delete":
                do_delete(conn, act["key"])
            elif op == "begin":
                tx[conn] = {}
            elif op == "commit":
                if tx[conn] is not None:
                    for k, v in tx[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None

        if chan == "changes":
            ch = last_changes
        elif chan == "total_changes":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, committed

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trig in (False, True):
            for chan in ("changes", "total_changes", "total_changes_both"):
                candidates.append((put_mode, trig, chan))

    for rec in hist:
        actions = rec["actions"]
        obs = rec["observed"]
        new_cands = []
        for (pm, tg, ch) in candidates:
            sim_ch, sim_committed = simulate(pm, tg, ch, actions)
            cnt = len(sim_committed)
            sm = sum(sim_committed.values())
            if sim_ch == obs["channel"] and cnt == obs["committed_count"] and sm == obs["committed_sum"]:
                new_cands.append((pm, tg, ch))
        candidates = new_cands

    goal = context.get("goal")
    actions = context.get("actions", [])

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for (pm, tg, ch) in candidates:
        sim_ch, sim_committed = simulate(pm, tg, ch, actions)
        if goal == "channel":
            results.add(sim_ch)
        elif goal == "committed_count":
            results.add(len(sim_committed))
        elif goal == "committed_sum":
            results.add(sum(sim_committed.values()))
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

